package com.ruoyi.hexu;
import java.util.*;
import java.time.LocalDate;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import static com.ruoyi.hexu.HexuStore.*;
import static com.ruoyi.hexu.BusinessException.require;

/** Statement comparison does not synthesize payment success. Cash adjustments need a different reviewer. */
public final class HexuReconciliation {
 private final HexuStore db;
 public HexuReconciliation(HexuStore db){this.db=db;}
 public List<Map<String,Object>> lines(Actor actor,long shop,String batch){db.manage(actor,shop,"FINANCE");require(db.optional("select id from hx_reconciliation_batch where id=? and shop_id=?",batch,shop)!=null,"账单批次不属于当前商城");return db.jdbc().queryForList("select * from hx_reconciliation_line where batch_id=? order by row_no",batch);}
 public Map<String,Object> summary(Actor actor,long shop){db.manage(actor,shop,"FINANCE");List<Map<String,Object>>totals=db.jdbc().queryForList("select category,coalesce(sum(amount),0) amount from hx_ledger where shop_id=? and category in ('RECEIPT','REFUND','PAYOUT','RECON_ADJUST') group by category",shop);long pending=db.jdbc().queryForObject("select count(*) from hx_reconciliation_line where shop_id=? and status not in ('MATCHED','RESOLVED')",Long.class,shop);List<Map<String,Object>>history=new ArrayList<>();for(int i=6;i>=0;i--){LocalDate day=LocalDate.now().minusDays(i);long amount=db.jdbc().queryForObject("select coalesce(sum(amount),0) from hx_ledger where shop_id=? and category in ('RECEIPT','REFUND','PAYOUT','RECON_ADJUST') and created_at>=? and created_at<?",Long.class,shop,java.sql.Timestamp.valueOf(day.atStartOfDay()),java.sql.Timestamp.valueOf(day.plusDays(1).atStartOfDay()));history.add(map("day",day.toString(),"amount",amount));}return map("totals",totals,"pendingRows",pending,"statementRows",db.jdbc().queryForObject("select count(*) from hx_reconciliation_line where shop_id=?",Long.class,shop),"history",history);}
 public Map<String,Object> submit(Actor actor,long shop,Map<String,Object>b){db.manage(actor,shop,"FINANCE");db.one("select id from hx_shop where id=? for update",shop);try{LocalDate.parse(str(b,"statementDate"));}catch(Exception e){throw new BusinessException("请填写有效账单日期");}require(b.get("rows") instanceof List,"请提供账单明细数组");List<?>input=(List<?>)b.get("rows");require(!input.isEmpty()&&input.size()<=5000,"每批账单须为1至5000条");Set<String>seen=new HashSet<>();List<Map<String,Object>>rows=new ArrayList<>();for(Object raw:input){require(raw instanceof Map,"账单明细格式无效");Map<String,Object>r=(Map<String,Object>)raw;String type=str(r,"type"),id=str(r,"businessId"),ref=str(r,"channelRef"),merchant=str(r,"merchantNo");require(Arrays.asList("PAYMENT","REFUND","PAYOUT").contains(type)&&id.length()>0&&id.length()<=64&&ref.length()>0&&ref.length()<=100&&merchant.length()>0&&merchant.length()<=80,"账单业务类型、编号或商户号无效");require(seen.add(type+":"+id),"账单含重复业务单号");require(r.get("amount")!=null&&number(r,"amount")>=0&&number(r,"amount")<=9000000000000L,"账单金额须为有效整数分");rows.add(map("type",type,"businessId",id,"channelRef",ref,"merchantNo",merchant,"amount",number(r,"amount")));}
 String hash;try{byte[]digest=MessageDigest.getInstance("SHA-256").digest(db.json(rows).getBytes(StandardCharsets.UTF_8));StringBuilder value=new StringBuilder();for(byte v:digest)value.append(String.format("%02x",v));hash=value.toString();}catch(Exception e){throw new IllegalStateException(e);}Map<String,Object>prior=db.optional("select * from hx_reconciliation_batch where shop_id=? and statement_date=? and content_hash=?",shop,str(b,"statementDate"),hash);if(prior!=null)return prior;
 String batch=id("DZ");db.jdbc().update("insert into hx_reconciliation_batch(id,shop_id,statement_date,source,content_hash,total_rows,status,created_by) values(?,?,?,'MANUAL',?,?,'QUEUED',?)",batch,shop,str(b,"statementDate"),hash,rows.size(),actor.key());int index=0;for(Map<String,Object>r:rows)db.jdbc().update("insert into hx_reconciliation_line(id,batch_id,shop_id,row_no,operation,business_id,channel_ref,merchant_no,channel_amount,status) values(?,?,?,?,?,?,?,?,?,'PENDING')",id("DZL"),batch,shop,++index,r.get("type"),r.get("businessId"),r.get("channelRef"),r.get("merchantNo"),r.get("amount"));db.audit(actor,shop,"STATEMENT_IMPORT",batch,null,map("source","MANUAL","rows",rows.size(),"hash",hash));return db.one("select * from hx_reconciliation_batch where id=?",batch);}
 private Map<String,Object> compare(Map<String,Object>line){String type=str(line,"operation"),id=str(line,"business_id");Map<String,Object>b="PAYMENT".equals(type)?db.optional("select p.*,o.shop_id from hx_payment p join hx_order o on o.id=p.order_id where p.id=?",id):"REFUND".equals(type)?db.optional("select r.*,o.merchant_no from hx_refund r join hx_order o on o.id=r.order_id where r.id=?",id):db.optional("select w.*,coalesce(w.merchant_no,s.merchant_no) as merchant_no from hx_withdrawal w join hx_shop s on s.id=w.shop_id where w.id=?",id);
 if(b==null)return map("status","UNKNOWN_BUSINESS","note","业务单号未找到，需核实外部账单");if(number(b,"shop_id")!=number(line,"shop_id"))return map("status","OUT_OF_SCOPE","note","业务单不属于当前商城");long expected="PAYOUT".equals(type)?number(b,"net"):number(b,"amount");if(!str(b,"merchant_no").equals(str(line,"merchant_no")))return map("status","MERCHANT_MISMATCH","note","商户号与原业务快照不一致");String terminal="PAYOUT".equals(type)?"PAID":"SUCCESS";if(!terminal.equals(str(b,"status")))return map("status","STATUS_MISMATCH","expected",expected,"note","账单报告成功，业务尚未收到对应成功回执，需先查询渠道并重试回执");String reference=str(b,"channel_ref");if("REFUND".equals(type)){Map<String,Object>receipt=db.optional("select channel_ref from hx_channel_event where business_id=? and event_type='REFUND_SUCCESS' and status='APPLIED'",id);reference=receipt==null?"":str(receipt,"channel_ref");}if(reference.isEmpty())return map("status","REFERENCE_MISMATCH","expected",expected,"note","原业务缺少成功渠道流水，请先查询并核实回执");if(!reference.equals(str(line,"channel_ref")))return map("status","REFERENCE_MISMATCH","expected",expected,"note","渠道流水与成功回执不一致");long delta=Math.subtractExact(number(line,"channel_amount"),expected);if(!"PAYMENT".equals(type))delta=-delta;return map("status",delta==0?"MATCHED":"AMOUNT_MISMATCH","expected",expected,"delta",delta,"note",delta==0?"金额及业务状态一致；人工导入不代表渠道验签":"渠道金额与原业务金额有差异，需凭证和双人复核");}
 public void process(String id){Map<String,Object>b=db.one("select * from hx_reconciliation_batch where id=? for update",id);if("COMPLETED".equals(str(b,"status")))return;for(Map<String,Object>line:db.jdbc().queryForList("select * from hx_reconciliation_line where batch_id=? and status='PENDING' order by row_no limit 100",id))writeComparison(line);long pending=db.jdbc().queryForObject("select count(*) from hx_reconciliation_line where batch_id=? and status='PENDING'",Long.class,id);db.jdbc().update("update hx_reconciliation_batch set processed_rows=total_rows-?,status=?,updated_at=CURRENT_TIMESTAMP where id=?",pending,pending==0?"COMPLETED":"PROCESSING",id);}
 private void writeComparison(Map<String,Object>line){Map<String,Object>r=compare(line);db.jdbc().update("update hx_reconciliation_line set status=?,expected_amount=?,difference=?,note=? where id=?",r.get("status"),r.get("expected"),r.get("delta"),r.get("note"),line.get("id"));}
 public Object recheck(Actor actor,String id){Map<String,Object>line=db.one("select * from hx_reconciliation_line where id=? for update",id);db.manage(actor,number(line,"shop_id"),"FINANCE");require(!"RESOLVED".equals(str(line,"status")),"该差异已形成调整流水，不能覆盖原复核结果");writeComparison(line);db.audit(actor,number(line,"shop_id"),"STATEMENT_RECHECK",id,line,db.one("select * from hx_reconciliation_line where id=?",id));return db.one("select * from hx_reconciliation_line where id=?",id);}
 public Map<String,Object> propose(Actor actor,String lineId,Map<String,Object>b){Map<String,Object>line=db.one("select * from hx_reconciliation_line where id=? for update",lineId);long shop=number(line,"shop_id");db.manage(actor,shop,"FINANCE");db.one("select id from hx_shop where id=? for update",shop);require("AMOUNT_MISMATCH".equals(str(line,"status"))&&number(line,"difference")!=0,"仅已确认业务终态的金额差异可申请账务调整");require(str(b,"reason").trim().length()>=2&&str(b,"reason").length()<=500,"请填写复核原因");require(b.get("uploads") instanceof List&&!((List<?>)b.get("uploads")).isEmpty()&&((List<?>)b.get("uploads")).size()<=9,"请上传1至9份财务凭证");for(Object proof:(List<?>)b.get("uploads"))require(db.optional("select id from hx_attachment where id=? and shop_id=? and purpose='FINANCE'",proof,shop)!=null,"财务凭证不属于当前商城或用途不正确");
 require(db.jdbc().queryForObject("select count(*) from hx_reconciliation_adjustment where shop_id=? and operation=? and business_id=? and channel_ref=? and status in ('PENDING','APPLIED')",Long.class,shop,line.get("operation"),line.get("business_id"),line.get("channel_ref"))==0,"该业务差异已申请或完成调整");String ref=id("ADJ");db.jdbc().update("insert into hx_reconciliation_adjustment(id,line_id,shop_id,operation,business_id,channel_ref,amount,status,requested_by,reason,evidence_json) values(?,?,?,?,?,?,?,'PENDING',?,?,?)",ref,lineId,shop,line.get("operation"),line.get("business_id"),line.get("channel_ref"),line.get("difference"),actor.key(),str(b,"reason"),db.json(map("uploads",b.get("uploads"),"line",line)));db.audit(actor,shop,"ADJUSTMENT_PROPOSE",ref,null,line);return db.one("select * from hx_reconciliation_adjustment where id=?",ref);}
 public Object review(Actor actor,String id,Map<String,Object>b){Map<String,Object>a=db.one("select * from hx_reconciliation_adjustment where id=? for update",id);long shop=number(a,"shop_id");db.manage(actor,shop,"FINANCE");require(!actor.key().equals(str(a,"requested_by")),"账务调整必须由另一位有权限的人员复核，申请人不能自审");require("PENDING".equals(str(a,"status")),"调整申请已处理");require(str(b,"reason").trim().length()>=2,"请填写复核意见");boolean approved=bool(b,"approve");if(approved){Map<String,Object>line=db.one("select * from hx_reconciliation_line where id=? for update",a.get("line_id")),current=compare(line);require("AMOUNT_MISMATCH".equals(str(current,"status"))&&number(current,"delta")==number(a,"amount"),"原业务状态或金额已变化，请先重新核对账单");db.one("select id from hx_shop where id=? for update",shop);require(db.jdbc().queryForObject("select count(*) from hx_reconciliation_adjustment where shop_id=? and operation=? and business_id=? and channel_ref=? and status='APPLIED'",Long.class,shop,a.get("operation"),a.get("business_id"),a.get("channel_ref"))==0,"同一业务差异已入账");db.jdbc().update("insert into hx_ledger(shop_id,member_id,category,amount,reference_id,detail) values(?,0,'RECON_ADJUST',?,?,?)",shop,a.get("amount"),id,db.json(map("originalBusiness",a.get("business_id"),"operation",a.get("operation"),"reason",b.get("reason"))));db.jdbc().update("update hx_reconciliation_line set status='RESOLVED',note='差异已形成独立调整流水，原业务单据保留' where id=?",a.get("line_id"));}
 db.jdbc().update("update hx_reconciliation_adjustment set status=?,reviewed_by=?,review_reason=?,reviewed_at=CURRENT_TIMESTAMP where id=?",approved?"APPLIED":"REJECTED",actor.key(),str(b,"reason"),id);db.audit(actor,shop,"ADJUSTMENT_REVIEW",id,a,b);return db.one("select * from hx_reconciliation_adjustment where id=?",id);}
}
